-- ── Cabal Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Cabal Cigars',
        'dominican',
        '2013 — Chris Arolfo, Webster (Texas)',
        'Sans usine — Kelner Boutique Factory, Santiago ; Initiative à Tabacalera La Isla (Hostos Fernández Quesada)',
        'stogiereview.com (Chris Arolfo fonde Cabal en 2013 après avoir dirigé le lounge The Smoke Ring à Webster, Texas) ; halfwheel.com « Cabal Adding Gran Cabal Size » ; luxurycigarclub.com « Cabal Initiative » (la nouveauté de la maison, faite à Tabacalera La Isla, avec la manière d''Hostos Fernández Quesada ; cape corojo colorado d''Équateur, sous-cape nicaraguayenne, tripes dominicaines et nicaraguayennes ; Cabal, Esoteric, Initiative) ; cabalcigars.com (Cabal roulée à la Kelner Boutique Factory avec Hendrik Kelner Jr. après près de deux ans d''essais — cape Bonao, sous-capes du Pérou et de Rép. dominicaine, tripes du Nicaragua, de Pennsylvanie et de Rép. dominicaine ; Esoteric, l''assemblage n° 19 des vingt et un essayés, en petites séries)',
        'Cabal — une cabale, dit le fondateur, au sens de gens réunis par un même dessein — est la marque de Chris Arolfo, qui tenait le lounge The Smoke Ring à Webster, au Texas, avant de la fonder en 2013. Il est allé chercher Hendrik Kelner Jr., le fils du maître de tabac de Davidoff, à la Kelner Boutique Factory de Santiago, dont l''atlas porte la fiche : près de deux ans d''essais, vingt et un assemblages, pour un cigare à cape Bonao — une feuille dominicaine rare sur une bague — sur sous-capes du Pérou et de République dominicaine et tripes du Nicaragua, de Pennsylvanie et de République dominicaine. L''assemblage n° 19, trop différent pour être Cabal, est devenu Esoteric, en petites séries.

Cabal est ainsi la quatrième marque de cet atlas à sortir de KBF, après Casdagli, Principle et The 73 de la fabrique elle-même. Sa nouveauté, Initiative, est sortie d''une autre fabrique dominicaine, Tabacalera La Isla, celle d''Hostos Fernández Quesada — cape corojo colorado d''Équateur, sous-cape nicaraguayenne —, et un détaillant la présente comme la première sortie de la maison depuis plus de six ans.

Six ans de silence, donc, entre deux cigares : la presse du métier n''a pas décrit la maison depuis 2015, et ce que la fiche sait de la suite vient de ses détaillants et de son site. L''atlas l''écrit parce que les deux fabriques sont nommées, et il dit ce qu''il ne sait pas.',
        '[{"name":"Cabal","color":"#4A3728","force":"Medium-Full","wrapper":"Bonao (Rép. dominicaine)","vitolas":[],"story":"2013 — vingt et un essais chez KBF avec Hendrik Kelner Jr. ; cape Bonao, une feuille dominicaine rare."},{"name":"Esoteric","color":"#8B1A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''assemblage n° 19 des essais — trop différent pour être Cabal, gardé en petites séries."},{"name":"Initiative","color":"#C9A96E","force":"Medium","wrapper":"Corojo colorado d''Équateur","vitolas":[],"story":"La nouveauté, à Tabacalera La Isla — la première sortie depuis plus de six ans, dit un détaillant."}]',
        'Cabal — a cabal, the founder says, in the sense of people gathered by a common purpose — is the brand of Chris Arolfo, who ran The Smoke Ring lounge in Webster, Texas, before founding it in 2013. He went to Hendrik Kelner Jr., the son of Davidoff''s tobacco master, at Kelner Boutique Factory in Santiago, whose entry this atlas carries: nearly two years of trials, twenty-one blends, for a cigar with a Bonao wrapper — a Dominican leaf rare on a band — over binders from Peru and the Dominican Republic and fillers from Nicaragua, Pennsylvania and the Dominican Republic. Blend no. 19, too different to be Cabal, became Esoteric, in small batches.

Cabal is thus the fourth brand of this atlas to come out of KBF, after Casdagli, Principle and the factory''s own The 73. Its new release, Initiative, came out of another Dominican factory, Tabacalera La Isla, that of Hostos Fernández Quesada — Ecuadorian Colorado corojo wrapper, Nicaraguan binder —, and a retailer presents it as the house''s first release in more than six years.

Six years of silence, then, between two cigars: the trade press has not described the house since 2015, and what the entry knows of what followed comes from its retailers and its site. This atlas writes it because both factories are named, and it says what it does not know.',
        '[{"name":"Cabal","color":"#4A3728","force":"Medium-Full","wrapper":"Bonao (Dominican Republic)","vitolas":[],"story":"2013 — twenty-one trials at KBF with Hendrik Kelner Jr.; Bonao wrapper, a rare Dominican leaf."},{"name":"Esoteric","color":"#8B1A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Blend no. 19 of the trials — too different to be Cabal, kept in small batches."},{"name":"Initiative","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorian Colorado corojo","vitolas":[],"story":"The new release, at Tabacalera La Isla — the first in more than six years, a retailer says."}]',
        'Cabal — una cábala, dice el fundador, en el sentido de gente reunida por un mismo propósito — es la marca de Chris Arolfo, que llevaba el lounge The Smoke Ring en Webster, Texas, antes de fundarla en 2013. Fue a buscar a Hendrik Kelner Jr., el hijo del maestro de tabaco de Davidoff, a la Kelner Boutique Factory de Santiago, cuya ficha lleva este atlas: cerca de dos años de ensayos, veintiuna ligadas, para un puro con capa Bonao — una hoja dominicana rara en una anilla — sobre capotes de Perú y República Dominicana y tripas de Nicaragua, Pensilvania y República Dominicana. La ligada n.º 19, demasiado distinta para ser Cabal, se convirtió en Esoteric, en pequeñas series.

Cabal es así la cuarta marca de este atlas que sale de KBF, tras Casdagli, Principle y The 73 de la propia fábrica. Su novedad, Initiative, salió de otra fábrica dominicana, Tabacalera La Isla, la de Hostos Fernández Quesada — capa corojo colorado de Ecuador, capote nicaragüense —, y un minorista la presenta como la primera salida de la casa en más de seis años.

Seis años de silencio, pues, entre dos puros: la prensa del oficio no ha descrito la casa desde 2015, y lo que la ficha sabe de lo que siguió viene de sus minoristas y de su sitio. Este atlas la escribe porque las dos fábricas están nombradas, y dice lo que no sabe.',
        '[{"name":"Cabal","color":"#4A3728","force":"Medium-Full","wrapper":"Bonao (República Dominicana)","vitolas":[],"story":"2013 — veintiún ensayos en KBF con Hendrik Kelner Jr.; capa Bonao, una hoja dominicana rara."},{"name":"Esoteric","color":"#8B1A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La ligada n.º 19 de los ensayos — demasiado distinta para ser Cabal, guardada en pequeñas series."},{"name":"Initiative","color":"#C9A96E","force":"Medium","wrapper":"Corojo colorado de Ecuador","vitolas":[],"story":"La novedad, en Tabacalera La Isla — la primera salida en más de seis años, dice un minorista."}]',
        'Cabal — eine Kabale, sagt der Gründer, im Sinne von Menschen, die ein gemeinsames Ziel versammelt — ist die Marke von Chris Arolfo, der die Lounge The Smoke Ring in Webster, Texas, führte, bevor er sie 2013 gründete. Er ging zu Hendrik Kelner Jr., dem Sohn des Tabakmeisters von Davidoff, in die Kelner Boutique Factory in Santiago, deren Eintrag dieser Atlas führt: fast zwei Jahre Versuche, einundzwanzig Blends, für eine Zigarre mit Bonao-Deckblatt — ein dominikanisches Blatt, selten auf einer Bauchbinde — über Umblättern aus Peru und der Dominikanischen Republik und Einlage aus Nicaragua, Pennsylvania und der Dominikanischen Republik. Blend Nr. 19, zu anders, um Cabal zu sein, wurde Esoteric, in kleinen Serien.

Cabal ist damit die vierte Marke dieses Atlas aus KBF, nach Casdagli, Principle und der fabrikeigenen The 73. Ihre Neuheit, Initiative, kam aus einer anderen dominikanischen Fabrik, Tabacalera La Isla, der von Hostos Fernández Quesada — ecuadorianisches Colorado-Corojo-Deckblatt, nicaraguanisches Umblatt —, und ein Händler stellt sie als erste Veröffentlichung des Hauses seit über sechs Jahren vor.

Sechs Jahre Schweigen also zwischen zwei Zigarren: Die Fachpresse hat das Haus seit 2015 nicht beschrieben, und was der Eintrag vom Weiteren weiß, stammt von seinen Händlern und seiner Seite. Dieser Atlas schreibt es, weil beide Fabriken benannt sind, und er sagt, was er nicht weiß.',
        '[{"name":"Cabal","color":"#4A3728","force":"Medium-Full","wrapper":"Bonao (Dominikanische Republik)","vitolas":[],"story":"2013 — einundzwanzig Versuche bei KBF mit Hendrik Kelner Jr.; Bonao-Deckblatt, ein seltenes dominikanisches Blatt."},{"name":"Esoteric","color":"#8B1A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Blend Nr. 19 der Versuche — zu anders, um Cabal zu sein, in kleinen Serien behalten."},{"name":"Initiative","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorianisches Colorado-Corojo","vitolas":[],"story":"Die Neuheit, bei Tabacalera La Isla — die erste Veröffentlichung seit über sechs Jahren, sagt ein Händler."}]',
        'Cabal——创始人说，是「密谋团」之意，指为同一目标聚在一起的人——是克里斯·阿罗尔福的品牌，他在得克萨斯州韦伯斯特经营 The Smoke Ring 雪茄吧，2013年创立此品牌。他找到大卫杜夫烟草大师之子小亨德里克·克尔纳，在圣地亚哥的 Kelner Boutique Factory——本图集载有其词条——近两年试验、二十一款配方，做出一支以博瑙茄衣（茄标上少见的多米尼加烟叶）配秘鲁与多米尼加茄套、尼加拉瓜、宾夕法尼亚与多米尼加填充的雪茄。第19号配方因与 Cabal 风格差异太大，成了小批量的 Esoteric。

Cabal 由此成为本图集第四个出自 KBF 的品牌，继 Casdagli、Principle 和工厂自有的 The 73 之后。它的新品 Initiative 出自另一家多米尼加工厂——奥斯托斯·费尔南德斯·克萨达的 Tabacalera La Isla——厄瓜多尔 Colorado corojo 茄衣、尼加拉瓜茄套，一家零售商称之为公司六年多来的首次新品。

于是两支雪茄之间是六年的沉默：行业媒体自2015年起未再描写这家公司，词条对其后续的了解来自零售商和它的网站。本图集写它，因为两家工厂都有名字，并说明自己不知道的部分。',
        '[{"name":"Cabal","color":"#4A3728","force":"Medium-Full","wrapper":"博瑙（多米尼加）","vitolas":[],"story":"2013年——在 KBF 与小亨德里克·克尔纳做了二十一次试验；博瑙茄衣，一种少见的多米尼加烟叶。"},{"name":"Esoteric","color":"#8B1A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"试验中的第19号配方——与 Cabal 差异太大，作为小批量保留。"},{"name":"Initiative","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔 Colorado corojo","vitolas":[],"story":"新品，在 Tabacalera La Isla 制作——一家零售商说是六年多来的首次新品。"}]',
        'كابال — عصبة، كما يقول المؤسّس، بمعنى أناس يجمعهم غرض واحد — علامةُ كريس أرولفو، الذي كان يدير صالون The Smoke Ring في ويبستر بتكساس قبل أن يؤسّسها سنة 2013. قصد هندريك كلنر الابن، ابن معلّم التبغ عند دافيدوف، في Kelner Boutique Factory في سانتياغو التي يحمل هذا الأطلس بطاقتها: قرابة سنتين من التجارب، إحدى وعشرون مزجة، لسيجار بغلاف بوناو — ورقة دومينيكية نادرة على حزام — على ورقتين رابطتين من بيرو وجمهورية الدومينيكان وحشوة من نيكاراغوا وبنسلفانيا وجمهورية الدومينيكان. والمزجة رقم 19، الأشدّ اختلافًا من أن تكون Cabal، صارت Esoteric بسلاسل صغيرة.

وهكذا كابال هي العلامة الرابعة في هذا الأطلس الخارجة من KBF، بعد Casdagli وPrinciple وThe 73 للمصنع نفسه. أمّا جديدها، Initiative، فخرج من مصنع دومينيكي آخر، Tabacalera La Isla، مصنع أوستوس فرنانديس كيسادا — غلاف كوروخو كولورادو إكوادوري، ورقة رابطة نيكاراغوية — ويقدّمه تاجر تجزئة إصدارَ الدار الأوّل منذ أكثر من ستّ سنين.

ستّ سنوات من الصمت إذن بين سيجارين: لم تصف صحافة المهنة الدار منذ 2015، وما تعرفه البطاقة عمّا تلا ذلك يأتي من تجّارها وموقعها. يكتبها هذا الأطلس لأنّ المصنعين مسمّيان، ويقول ما لا يعرفه.',
        '[{"name":"Cabal","color":"#4A3728","force":"Medium-Full","wrapper":"بوناو (جمهورية الدومينيكان)","vitolas":[],"story":"2013 — إحدى وعشرون تجربة في KBF مع هندريك كلنر الابن؛ غلاف بوناو، ورقة دومينيكية نادرة."},{"name":"Esoteric","color":"#8B1A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"المزجة رقم 19 من التجارب — أشدّ اختلافًا من أن تكون Cabal، أُبقيت بسلاسل صغيرة."},{"name":"Initiative","color":"#C9A96E","force":"Medium","wrapper":"كوروخو كولورادو إكوادوري","vitolas":[],"story":"الجديد، في Tabacalera La Isla — الإصدار الأوّل منذ أكثر من ستّ سنين، كما يقول تاجر تجزئة."}]')
