INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Jas Sum Kral','Casa 1910','Ortega Cigars','La Sirena','Reinado','Cabal Cigars')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 220';
INSERT INTO `moderation_log`
  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 220','systeme','six_reports_ecrits_avec_leur_etat','marque',0,
   'Jas Sum Kral, Casa 1910, Ortega, La Sirena, Reinado, Cabal : chaque fiche dit ce qu elle sait et ou s arrete ce qu elle sait — fabrique non publiee, presse muette depuis telle annee, site muet depuis 2023'),
  (NULL,'migration 220','systeme','exception_nommee_fabrique_non_publiee','marque',0,
   'Pas de fiche sans fabrique nommee vise l invention. Quand la maison (JSK) ou la presse (Casa 1910) ecrit que la fabrique n est pas publiee, le silence est un fait documente : deux exceptions, nommees dans les fiches'),
  (NULL,'migration 220','systeme','cinq_non_ecrits','marque',0,
   'Aragon : fabrique sans marque propre, nommee dans JSK. Las Cumbres : rien depuis 2017. Amendola : rien depuis 2023, boutique fermee. Isabela : fabrique non nommee par la presse. Cubanacan : rien depuis 2018');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Jas Sum Kral','Casa 1910','Ortega Cigars','La Sirena','Reinado','Cabal Cigars')) = 6 AS six_fiches,
  (SELECT `brands` LIKE '%Casa 1910%' FROM `producer_countries` WHERE `id` = 'mexico') AS mexique_annonce,
  (SELECT `brands` LIKE '%Jas Sum Kral%' AND `brands` LIKE '%Reinado%' FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT `brands` LIKE '%Cabal%' FROM `producer_countries` WHERE `id` = 'dominican') AS dominicaine_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 220') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
